-- =============================================================================
-- Source: NOAA Global Historical Climatology Network - Daily (GHCN-Daily),
-- parquet partitions by year and element on the public AWS bucket:
--   s3a://noaa-ghcn-pds/parquet/by_year/YEAR=<yyyy>/ELEMENT=<TMAX|TMIN>/
-- One Lightning filestore table per (year, element): 2024 and 2025, TMAX and TMIN,
-- each 9 parquet files with every station worldwide.
-- Licence: CC0-1.0 (public domain), https://registry.opendata.aws/noaa-ghcn/
-- Format: parquet FILESTORE table with the public-bucket options (no credentials);
-- schema as inferred: ID, DATE yyyymmdd, DATA_VALUE (tenths of a degree C),
-- M_FLAG, Q_FLAG, S_FLAG, OBS_TIME.
-- Generated by scripts/make_cw_sql.py from the gateway's register_ghcn templates
-- (gateway/templates.py): the same statements the registrar plan sends.
-- Rate limit: none (anonymous S3). An uncached read scans the 9 files of a
-- partition, so only the station-filtered views are read, and they are cached.
-- Caveats:
--   1. The views keep the 57 ids of seeds/stations.json plus USW00013740
--      (Richmond, VA), the validation station of the degree-day check in
--      09_cw_ghcn_select.sql. No seed utility uses it.
--   2. The database CW_GHCN exists (02_cw_stations_create.sql); run with
--      --skip-exists when the tables or views already exist.
--   3. The raw tables are never cached (millions of rows each).
-- Status and counts: ../README.md.
-- =============================================================================

-- Step 1: one filestore table per (year, element).
CREATE LIGHTNING FILESTORE TABLE ghcn_2025_tmax FROM CW_GHCN FORMAT PARQUET OPTIONS ( PATH "s3a://noaa-ghcn-pds/parquet/by_year/YEAR=2025/ELEMENT=TMAX/", inferSchema "true", isS3BucketPublic "true", useS3PathStyleAccess "true", s3Endpoint "s3.us-east-1.amazonaws.com" );
CREATE LIGHTNING FILESTORE TABLE ghcn_2025_tmin FROM CW_GHCN FORMAT PARQUET OPTIONS ( PATH "s3a://noaa-ghcn-pds/parquet/by_year/YEAR=2025/ELEMENT=TMIN/", inferSchema "true", isS3BucketPublic "true", useS3PathStyleAccess "true", s3Endpoint "s3.us-east-1.amazonaws.com" );
CREATE LIGHTNING FILESTORE TABLE ghcn_2024_tmax FROM CW_GHCN FORMAT PARQUET OPTIONS ( PATH "s3a://noaa-ghcn-pds/parquet/by_year/YEAR=2024/ELEMENT=TMAX/", inferSchema "true", isS3BucketPublic "true", useS3PathStyleAccess "true", s3Endpoint "s3.us-east-1.amazonaws.com" );
CREATE LIGHTNING FILESTORE TABLE ghcn_2024_tmin FROM CW_GHCN FORMAT PARQUET OPTIONS ( PATH "s3a://noaa-ghcn-pds/parquet/by_year/YEAR=2024/ELEMENT=TMIN/", inferSchema "true", isS3BucketPublic "true", useS3PathStyleAccess "true", s3Endpoint "s3.us-east-1.amazonaws.com" );

-- Step 2: station-filtered views, one per raw table, same columns.
CREATE SCHEMASTORE VIEW ghcn_2025_tmax WITH CONTAINER cw AS SELECT ID, DATE, DATA_VALUE, M_FLAG, Q_FLAG, S_FLAG, OBS_TIME FROM CW_GHCN.ghcn_2025_tmax WHERE ID IN ('USW00003017', 'USW00003927', 'USW00003940', 'USW00012839', 'USW00012842', 'USW00012916', 'USW00012960', 'USW00013722', 'USW00013737', 'USW00013739', 'USW00013740', 'USW00013781', 'USW00013866', 'USW00013874', 'USW00013876', 'USW00013883', 'USW00013963', 'USW00013967', 'USW00013994', 'USW00013996', 'USW00014734', 'USW00014739', 'USW00014740', 'USW00014745', 'USW00014765', 'USW00014820', 'USW00014821', 'USW00014836', 'USW00014837', 'USW00014839', 'USW00014842', 'USW00014913', 'USW00014922', 'USW00014933', 'USW00014944', 'USW00022521', 'USW00023050', 'USW00023174', 'USW00023183', 'USW00023234', 'USW00024011', 'USW00024018', 'USW00024033', 'USW00024090', 'USW00024131', 'USW00024229', 'USW00024233', 'USW00093720', 'USW00093721', 'USW00093730', 'USW00093817', 'USW00093819', 'USW00093821', 'USW00094728', 'USW00094823', 'USW00094846', 'USW00094847');
